<?php
use App\Models\PilketosPeriode; use App\Services\TahunAkademikResolver; use Livewire\Attributes\Layout; use Livewire\Volt\Component;
new #[Layout('layouts.pilketos')] class extends Component { public $periodes; public string $tahun='', $nama='', $status='draft'; public bool $hasilPublik=false; public function mount(TahunAkademikResolver $r):void{$this->periodes=PilketosPeriode::latest('tahun')->get();$this->tahun=$r->resolve()['tahun'];} public function save():void{$d=$this->validate(['tahun'=>['required','string','max:11'],'nama'=>['required','string','max:100'],'status'=>['required','in:draft,aktif,ditutup'],'hasilPublik'=>['boolean']]);if($d['status']==='aktif')PilketosPeriode::where('status','aktif')->update(['status'=>'ditutup']);PilketosPeriode::create(['tahun'=>$d['tahun'],'nama'=>$d['nama'],'status'=>$d['status'],'hasil_publik'=>$d['hasilPublik'],'created_by'=>auth()->id()]);$this->periodes=PilketosPeriode::latest('tahun')->get();$this->reset('nama','status','hasilPublik');$this->status='draft';} public function destroy(int $id):void{$p=PilketosPeriode::findOrFail($id);if($p->suara()->exists()||$p->tokens()->exists()||$p->hakPilih()->exists()){$this->addError('periode','Periode yang sudah memiliki data tidak dapat dihapus.');return;}$p->delete();$this->periodes=PilketosPeriode::latest('tahun')->get();}}; ?>
<div><a wire:navigate href="{{route('guru.dashboard')}}">← Dashboard</a><h1 class="mt-4 text-3xl font-black">Periode & pengaturan</h1><form wire:submit="save" class="mt-6 grid gap-3 rounded bg-white p-5 shadow md:grid-cols-2"><input wire:model="tahun" class="rounded border-slate-300"><input wire:model="nama" placeholder="Nama pemilihan" class="rounded border-slate-300"><select wire:model="status"><option value="draft">Draft</option><option value="aktif">Aktif</option><option value="ditutup">Ditutup</option></select><label><input wire:model="hasilPublik" type="checkbox"> Publikasikan hasil</label><button class="rounded bg-emerald-700 p-2 font-bold text-white md:col-span-2">Buat periode</button></form><x-input-error :messages="$errors->all()" class="mt-3"/><section class="mt-6 space-y-3">@foreach($periodes as $p)<article class="rounded bg-white p-4 shadow"><b>{{$p->tahun}} — {{$p->nama}}</b> ({{$p->status}})<button wire:click="destroy({{$p->id}})" class="ml-4 text-red-700">Hapus</button></article>@endforeach</section></div>
